std::wstring wide(const std::string& s){if(s.empty())return {};int n=MultiByteToWideChar(CP_UTF8,0,s.c_str(),-1,nullptr,0);std::wstring w(static_cast<size_t>(n),L'\0');MultiByteToWideChar(CP_UTF8,0,s.c_str(),-1,w.data(),n);if(!w.empty())w.pop_back();return w;}
std::string utf8(const std::wstring& w){if(w.empty())return {};int n=WideCharToMultiByte(CP_UTF8,0,w.c_str(),-1,nullptr,0,nullptr,nullptr);std::string s(static_cast<size_t>(n), '\0');WideCharToMultiByte(CP_UTF8,0,w.c_str(),-1,s.data(),n,nullptr,nullptr);if(!s.empty())s.pop_back();return s;}
HWND control(HWND parent,const wchar_t* cls,const wchar_t* text,DWORD style,int id){return CreateWindowExW(0,cls,text,WS_CHILD|style,0,0,100,25,parent,reinterpret_cast<HMENU>(static_cast<INT_PTR>(id)),GetModuleHandleW(nullptr),nullptr);}
HWND label(HWND p,const wchar_t* text){return control(p,L"STATIC",text,SS_LEFT,0);}
HWND edit(HWND p,int id){return control(p,L"EDIT",L"",WS_BORDER|ES_AUTOHSCROLL,id);}
HWND button(HWND p,const wchar_t* text,int id){return control(p,L"BUTTON",text,BS_PUSHBUTTON,id);}
void comboAdd(HWND h,const std::wstring& text){SendMessageW(h,CB_ADDSTRING,0,reinterpret_cast<LPARAM>(text.c_str()));}
int comboIndex(HWND h){int i=static_cast<int>(SendMessageW(h,CB_GETCURSEL,0,0));return i<0?0:i;}
std::string comboValue(HWND h){int i=comboIndex(h);wchar_t b[128]{};SendMessageW(h,CB_GETLBTEXT,i,reinterpret_cast<LPARAM>(b));return utf8(b);}
std::wstring statusText(const std::string& s){return wide(s);}
